  mem = MEM,
  read_string = function(p, n) return fk_str(MEM, MEMSIZE, p, n) end,
  memio = {
    ld8 = function(a) return ld8(MEM, MEMSIZE, a) end,
    ld16 = function(a) return ld16(MEM, MEMSIZE, a) end,
    ld32 = function(a) return ld32(MEM, MEMSIZE, a) end,
    ldf32 = function(a) return bits_to_f32(ld32(MEM, MEMSIZE, a)) end,
    ldf64 = function(a) return ld_f64(MEM, MEMSIZE, a) end,
    st8 = function(a, v) st8b(MEM, MEMSIZE, a, v) end,
    st16 = function(a, v) st16(MEM, MEMSIZE, a, v) end,
    st32 = function(a, v) st32(MEM, MEMSIZE, a, v) end,
    stf32 = function(a, v) st32(MEM, MEMSIZE, a, f32_to_bits(v)) end,
    stf64 = function(a, v) st_f64(MEM, MEMSIZE, a, v) end,
    wstr = function(a, s) fk_wstr(MEM, MEMSIZE, a, s) end,
    size = function() return MEMSIZE end,
  },
  persist = {
    mode = "none",
    build = "",
    memory = function() return MEM, MEMSIZE end,
    adopt = function(t, n) MEM = t MEMSIZE = n SHBOUND = n < 2097152 and n or 2097152 S1 = t[1] MEMPACK.memreset(n) end,
    grow_hook = MEMPACK.grow_hook,
    prebuild = function(n) return MEMPACK.prebuild(MEM, n) end,
    globals = function(t) t = t or {} t[1] = g0 return t end,
    setglobals = function(t) g0 = t[1] if g0 % 8 ~= 0 then error("fklua: restored global 0 is not 8-aligned; the save was written by an incompatible build", 0) end end,
  },
  rt = { f32_to_bits = f32_to_bits, bits_to_f32 = bits_to_f32,
         f64_to_bits = f64_to_bits, f32 = f32, nan_mode = "canonical",
         boxf32 = boxf32, boxf64 = boxf64 } }
end
